import numpy as np

from seaborn.utils import _check_argument


class _ECDFPlotter:

    def __init__(self, stat="proportion", complementary=False):
        """Store ECDF parameters on the plotter instance."""
        _check_argument("stat", ["count", "percent", "proportion"], stat)
        self.stat = stat
        self.complementary = complementary

    @staticmethod
    def _eval_univariate_core(x, weights, stat, complementary):
        """Core univariate ECDF computation, usable as a static helper."""
        sorter = x.argsort()
        x = x[sorter]
        weights = weights[sorter]
        y = weights.cumsum()

        if stat in ["percent", "proportion"]:
            y = y / y.max()
        if stat == "percent":
            y = y * 100

        x = np.r_[-np.inf, x]
        y = np.r_[0, y]

        if complementary:
            y = y.max() - y

        return y, x

    def evaluate_univariate(self, x, weights):
        """Evaluate the univariate ECDF using stored parameters."""
        return self._eval_univariate_core(
            x, weights, self.stat, self.complementary,
        )

    def __call__(self, x1, x2=None, weights=None):
        """Compute ECDF, dispatching univariate/bivariate."""
        x1 = np.asarray(x1)
        if weights is None:
            weights = np.ones_like(x1)
        else:
            weights = np.asarray(weights)

        if x2 is None:
            return self.evaluate_univariate(x1, weights)
        else:
            raise NotImplementedError("Bivariate ECDF is not implemented")

